<script setup lang="ts">
import { onLoad } from '@dcloudio/uni-app';import { computed,ref } from 'vue';import type { SchoolPeriod } from '@codestrike/contracts';import { createStudentApiClient } from '../../api/client';import CsHeader from '../../components/CsHeader.vue'
const api=createStudentApiClient(),name=ref(''),startWeek=ref('2026-10-26'),weekdayIndex=ref(1),startPeriodIndex=ref(2),endPeriodIndex=ref(3),room=ref(''),repeatIndex=ref(3),periods=ref<SchoolPeriod[]>([]),feedback=ref('');const weekdays=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],repeats=Array.from({length:12},(_,i)=>i+1);const preview=computed(()=>repeats[repeatIndex.value]+' weekly occurrence(s), including the selected start week')
onLoad(async options=>{if(typeof options?.date==='string')startWeek.value=weekMonday(options.date);periods.value=await api.listSchoolPeriods()})
function weekMonday(value:string){const [y,m,d]=value.split('-').map(Number),date=new Date(Date.UTC(y,m-1,d)),day=date.getUTCDay()||7;date.setUTCDate(date.getUTCDate()-(day-1));return `${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}-${String(date.getUTCDate()).padStart(2,'0')}`}
async function save(){const result=await api.createCourse({name:name.value,actualStartWeek:startWeek.value,weekday:weekdayIndex.value+1,startPeriod:periods.value[startPeriodIndex.value]?.period||1,endPeriod:periods.value[endPeriodIndex.value]?.period||1,room:room.value,repeatCount:repeats[repeatIndex.value]});feedback.value=result.message}
</script>
<template><view class="page-shell"><CsHeader back eyebrow="UI-17 · EXAMPLE CALENDAR" title="Manual Course"/><view class="content"><view class="notice">Example / Mock period timetable — not claimed as Fuzhou University’s official schedule.</view><view class="form"><text class="label">COURSE NAME</text><input v-model="name" placeholder="e.g. Design Research"/><text class="label">ACTUAL START WEEK (MONDAY)</text><picker mode="date" :value="startWeek" @change="startWeek=($event as any).detail.value"><view class="input">{{startWeek}}</view></picker><text class="label">WEEKDAY</text><picker :range="weekdays" :value="weekdayIndex" @change="weekdayIndex=Number(($event as any).detail.value)"><view class="input">{{weekdays[weekdayIndex]}}</view></picker><view class="split"><view><text class="label">START PERIOD</text><picker :range="periods" range-key="period" :value="startPeriodIndex" @change="startPeriodIndex=Number(($event as any).detail.value)"><view class="input">Period {{periods[startPeriodIndex]?.period}} · {{periods[startPeriodIndex]?.startTime}}</view></picker></view><view><text class="label">END PERIOD</text><picker :range="periods" range-key="period" :value="endPeriodIndex" @change="endPeriodIndex=Number(($event as any).detail.value)"><view class="input">Period {{periods[endPeriodIndex]?.period}} · {{periods[endPeriodIndex]?.endTime}}</view></picker></view></view><text class="label">CLASSROOM · OPTIONAL</text><input v-model="room" placeholder="Example Room B204"/><text class="label">FINITE WEEKLY REPEAT</text><picker :range="repeats" :value="repeatIndex" @change="repeatIndex=Number(($event as any).detail.value)"><view class="input">{{repeats[repeatIndex]}} weeks</view></picker><text class="preview">{{preview}}</text><button class="save" @click="save">Save Course</button></view><text v-if="feedback" class="feedback">{{feedback}}</text></view></view></template>
<style scoped>.content{max-width:820px;margin:auto;padding:26rpx}.notice,.form,.feedback{margin-top:18rpx;padding:24rpx;border-radius:22rpx}.notice{color:#684c00;background:#ffe5a8;font-size:21rpx;line-height:1.5}.form{background:#fff;border:1rpx solid #dce4ed}.label{display:block;margin-top:22rpx;color:#68778d;font-size:19rpx;font-weight:900;letter-spacing:1.2rpx}.label:first-child{margin-top:0}.input,input{width:100%;margin-top:9rpx;padding:19rpx;background:#f1f4f7;border-radius:15rpx;font-size:22rpx}.split{display:grid;grid-template-columns:1fr 1fr;gap:12rpx}.preview{display:block;margin-top:18rpx;color:#536983;font-size:20rpx}.save{margin:24rpx 0 0;padding:21rpx;color:#0a1830;background:#d9ff74;border-radius:16rpx;font-weight:900}.feedback{display:block;color:#075b49;background:#dff8f1;font-size:21rpx}@media(min-width:680px){.content{padding:40px}}</style>
